 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    # Grid lines are the color that forms full horizontal and vertical bands,
    # even when a few intersections are replaced by markers.
    scores = {}
    for color in colors:
        rs = [r for r in range(h) if sum(x == color for x in grid[r]) >= 0.7 * w]
        cs = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.7 * h]
        scores[color] = (len(rs) + len(cs), rs, cs)
    line = max(colors, key=lambda v: scores[v][0])
    _, rows, cols = scores[line]
    if len(rows) < 2 or len(cols) < 2:
        return []
    counts = {}
    for row in grid:
        for v in row:
            if v != line:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    out = []
    for r0, r1 in zip(rows, rows[1:]):
        outrow = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            mark = corners[0]
            outrow.append(mark if mark != line and all(x == mark for x in corners) else background)
        out.append(outrow)
    return out

if __name__ == '__main__':
    demo = [[6] * 26 for _ in range(24)]
    for r in (0, 11, 22):
        for c in range(26): demo[r][c] = 8
    for c in (2, 12, 22):
        for r in range(24): demo[r][c] = 8
    for r, cs in ((0, (2, 12)), (11, (2, 12, 22)), (22, (2, 12, 22))):
        for c in cs: demo[r][c] = 2
    assert transform(demo) == [[2, 6], [2, 2]]
    print('demo check passed')
