    rows, cols = candidates[line]
    counts = {}
    for row in grid:
        for value in row:
            if value != line:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    output = []
    for r0, r1 in zip(rows, rows[1:]):
        outrow = []
        for c0, c1 in zip(cols, cols[1:]):
