    colors = {x for row in grid for x in row}
    axes = {}
    for col in colors:
        rs = [r for r in range(h) if sum(x == col for x in grid[r]) >= .7 * w]
        cs = [c for c in range(w) if sum(grid[r][c] == col for r in range(h)) >= .7 * h]
        if len(rs) >= 2 and len(cs) >= 2:
            axes[col] = (rs, cs)
    line = min(axes, key=lambda x: len(axes[x][0]) + len(axes[x][1]))
    rs, cs = axes[line]
    counts = {}
    for row in grid:
        for x in row:
            if x != line:
                counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    return [[grid[r0][c0] if grid[r0][c0] != line and grid[r0][c0] == grid[r0][c1] == grid[r1][c0] == grid[r1][c1] else bg
