 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Grid is tiled by full-color separator stripes; identify their color and coordinates.
    colors = {v for row in grid for v in row}
    candidates = {}
    for color in colors:
        rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= .7 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= .7 * h]
        if len(rows) >= 2 and len(cols) >= 2:
            candidates[color] = (rows, cols)
    line = min(candidates, key=lambda c: len(candidates[c][0]) + len(candidates[c][1]))
    rows, cols = candidates[line]
    # The common non-line color is the unmarked panel value.
    freq = {}
    for row in grid:
        for v in row:
            if v != line:
                freq[v] = freq.get(v, 0) + 1
    background = max(freq, key=freq.get)
    # A panel is marked when its four grid intersections carry the same color.
    out = []
    for r0, r1 in zip(rows, rows[1:]):
        outrow = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            outrow.append(corners[0] if corners[0] != line and len(set(corners)) == 1 else background)
        out.append(outrow)
    return out

if __name__ == '__main__':
    # Both demonstrated pairs are reproducible by this transform.
    d1 = [[6] * 26 for _ in range(24)]
    for r in (0, 11, 22):
        for c in range(26): d1[r][c] = 8
    for c in (2, 12, 22):
