    for r, cs in ((0, (2, 12)), (11, (2, 12, 22)), (22, (2, 12, 22))):
        for c in cs: d1[r][c] = 2
    assert transform(d1) == [[2, 6], [2, 2]]
    d2 = [[0] * 8 for _ in range(14)]
    for r in range(14):
        for c in (1, 7): d2[r][c] = 8
    for r in (2, 13):
        for c in range(8): d2[r][c] = 8
    for r, c in ((2, 1), (2, 7), (13, 1), (13, 7)): d2[r][c] = 7
    assert transform(d2) == [[7]]
    print('both demos reproduced')
